function pathFor(path, south) {
  if (path.includes('exhibition')) return south ? '/exhibition-south/' : '/exhibition/';
  if (path.includes('speakers')) return south ? '/south-forum-speakers/' : '/speakers/';
  if (path.includes('felicitation') || path.includes('business-excellence-awards')) return south ? '/felicitation/' : '/business-excellence-awards/';
  return south ? '/conference-south/' : '/';
}

function useForumContent(forum) {
  const [content,setContent]=useState(null);
  useEffect(()=>{let active=true;api(`/public/forum/${forum}`).then(data=>active&&setContent(data)).catch(()=>{});return()=>{active=false}},[forum]);
  return content;
}

function youtubeId(url='') {
  const value=String(url).trim();
  if(/^[\w-]{6,}$/.test(value))return value;
  try {
    const parsed=new URL(value);
    if(parsed.hostname==='youtu.be')return parsed.pathname.split('/').filter(Boolean)[0]||'';
    if(parsed.hostname.endsWith('youtube.com')||parsed.hostname.endsWith('youtube-nocookie.com')) {
      if(parsed.searchParams.get('v'))return parsed.searchParams.get('v');
      const parts=parsed.pathname.split('/').filter(Boolean);
      if(['embed','shorts','live'].includes(parts[0]))return parts[1]||'';
    }
  } catch { return ''; }
  return '';
}
function YoutubeVideo({url,background=false,title}) { const id=youtubeId(url); if(!id)return null; const src=`https://www.youtube-nocookie.com/embed/${id}?autoplay=1&mute=1&loop=1&playlist=${id}&playsinline=1&rel=0&controls=${background?0:1}&modestbranding=1`; return <iframe className={background?'youtube-background':'youtube-video'} src={src} title={title} allow="autoplay; encrypted-media; picture-in-picture" referrerPolicy="strict-origin-when-cross-origin" allowFullScreen={!background}/> }
function AnimatedNumber({value}) { const target=Number(String(value).replace(/\D/g,'')); const suffix=String(value).replace(/[\d,]/g,''); const [shown,setShown]=useState(0); useEffect(()=>{if(!target)return;let frame,start;const tick=time=>{start??=time;const progress=Math.min(1,(time-start)/1500);setShown(Math.round(target*(1-Math.pow(1-progress,3))));if(progress<1)frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame)},[target]); return <>{shown}{suffix}</> }

export function SiteHeader({ path, section = 'conference' }) {
  const [open, setOpen] = useState(false);
  const south = path.includes('south') || path === '/felicitation/';
  const secondary = section === 'blog' ? [['Latest Articles','/blog/'],['India Forum','/'],['South Forum','/conference-south/'],['Speakers','/speakers/'],['Contact Us','/#contact']] : section === 'exhibition' ? [['About Us','#about'],['Exhibit','#exhibit'],['Testimonials','#testimonials'],['Previous Edition','#previous']] : section === 'awards' ? [['About','#about'],['Categories','#categories'],['Guidelines','#guidelines'],['Timeline','#timeline'],['Contact Us','#contact']] : section === 'felicitation' ? [['About','#about'],['Contact Us','#contact']] : [['Speakers','#speakers'],['Agenda','#agenda'],['Watch','#watch'],['Delegate Pass','#passes'],['Contact Us','#contact']];
  const primary = south ? [['Conference','/conference-south/'],['Exhibition','/exhibition-south/'],['Felicitation','/felicitation/'],['Blog','/blog/']] : [['Conference','/'],['Exhibition','/exhibition/'],['Business Excellence Awards','/business-excellence-awards/'],['Blog','/blog/']];
  const delegateTarget = south ? '/conference-south/#passes' : '/#passes';
  const registerTarget = delegateTarget;
  const logo = south ? A('south-forum-logo-horizontal.png') : A('2025/07/Logo.jpg');
  return <>
    <header className={`ref-header ${south?'south-header':''}`}>
      <div className="ref-primary">
        <div className="forum-switch" aria-label="Choose forum">
          <Link className={!south?'active':''} to={pathFor(path,false)}>India Forum</Link>
          <Link className={south?'active':''} to={pathFor(path,true)}>South Forum</Link>
        </div>
        <nav className="primary-menu">{primary.map(([label,url])=><Link key={label} to={url}>{label}</Link>)}</nav>
        <div className="header-actions"><a href={registerTarget}>Register Now</a></div>
      </div>
      <div className="ref-secondary-row">
        <Link className="active-forum-logo" to={south?'/conference-south/':'/'}><img src={logo} alt={south?'Retail Jeweller South Forum':'Retail Jeweller India Forum'}/></Link>
        <button className="header-menu-toggle" aria-expanded={open} onClick={()=>setOpen(!open)}><span/><span/><span/><b className="sr-only">Menu</b></button>
        <nav className={`ref-secondary ${open?'open':''}`}>{secondary.map(([label,url])=>url.startsWith('/')?<Link key={label} to={url} onClick={()=>setOpen(false)}>{label}</Link>:<a key={label} href={url} onClick={()=>setOpen(false)}>{label}</a>)}{primary.map(([label,url])=><Link className="mobile-primary-link" key={`mobile-${label}`} to={url} onClick={()=>setOpen(false)}>{label}</Link>)}</nav>
      </div>
    </header>
    <a className="delegate-ticker" href={delegateTarget} aria-label="Go to delegate passes"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M4 7h24v6a3 3 0 0 0 0 6v6H4v-6a3 3 0 0 0 0-6V7Z"/><path d="M16 9v14"/></svg><span>Delegate Pass</span></a>
  </>;
}

function SectionTitle({children}){return <h2 className="ref-section-title">{children}</h2>}
