function EnquiryModal({open,onClose,type='Exhibition enquiry'}){const [busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');if(!open)return null;async function submit(event){event.preventDefault();setBusy(true);setError('');const form=event.currentTarget;const values=Object.fromEntries(new FormData(form));try{const result=await api('/public/forms/contact/submit',{method:'POST',body:JSON.stringify({...values,enquiry_type:type})});setMessage(result.message||'Thank you. Our team will contact you shortly.');form.reset()}catch(e){setError(e.message)}finally{setBusy(false)}}return <div className="enquiry-backdrop" role="presentation" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="enquiry-modal" role="dialog" aria-modal="true" aria-labelledby="enquiry-title"><button className="modal-close" onClick={onClose} aria-label="Close">×</button><h2 id="enquiry-title">{type}</h2><p>Share your details and the Retail Jeweller team will contact you.</p>{message?<div className="status" role="status">{message}</div>:<form onSubmit={submit}>{error&&<p className="error" role="alert">{error}</p>}<label>Full name<input name="name" autoComplete="name" required/></label><label>Company<input name="company" autoComplete="organization" required/></label><label>Email<input name="email" type="email" autoComplete="email" required/></label><label>Mobile number<input name="phone" type="tel" autoComplete="tel" required/></label><label>Message<textarea name="message" rows="4"/></label><label className="consent"><input name="consent" type="checkbox" value="yes" required/> I agree to the privacy policy and consent to being contacted.</label><button className="ref-button" type="submit" disabled={busy}>{busy?'Submitting…':'Submit enquiry'}</button></form>}</section></div>}
function VideoModal({video,onClose}){useEffect(()=>{if(!video)return undefined;const close=event=>event.key==='Escape'&&onClose();document.addEventListener('keydown',close);return()=>document.removeEventListener('keydown',close)},[video,onClose]);if(!video)return null;const id=youtubeId(video.url);return <div className="video-modal-backdrop" role="presentation" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="video-modal" role="dialog" aria-modal="true" aria-label={video.title||'Highlight video'}><button type="button" className="modal-close" onClick={onClose} aria-label="Close video">×</button>{id?<iframe src={`https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0`} title={video.title||'Highlight video'} allow="autoplay; encrypted-media; picture-in-picture" referrerPolicy="strict-origin-when-cross-origin" allowFullScreen/>:<p>This video link is not valid.</p>}</section></div>}
function Gallery({items, label='Previous Event Glimpses',target='/previous-edition-highlights/'}){const [index,setIndex]=useState(0);if(!items?.length)return null;return <section className="ref-section ref-gallery" id="previous"><SectionTitle>{label}</SectionTitle><div className="gallery-frame"><img src={items[index].image} alt={items[index].alt||label}/><button className="prev" onClick={()=>setIndex((index-1+items.length)%items.length)}>‹</button><button className="next" onClick={()=>setIndex((index+1)%items.length)}>›</button></div><Button light href={items[index].target_url||target}>View More</Button></section>}
