function SocialIcon({type}){if(type==='linkedin')return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4ZM3.5 9H6.5V21H3.5ZM9 9h3v1.7c.9-1.3 2.1-2 3.8-2 3.2 0 4.2 2.1 4.2 5.5V21h-3v-6.1c0-1.9-.4-3.2-2.3-3.2-2 0-2.7 1.4-2.7 3.5V21H9Z"/></svg>;if(type==='instagram')return <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle className="fill" cx="17.5" cy="6.5" r="1"/></svg>;if(type==='facebook')return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 21v-8h3l.5-3H14V8.2c0-.9.3-1.7 1.8-1.7H18V3.8c-.7-.1-1.5-.2-2.5-.2-2.6 0-4.5 1.6-4.5 4.6V10H8v3h3v8Z"/></svg>;if(type==='x')return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h4.6l4.2 5.6L17.7 3H20l-6.1 7.2L20.5 21h-4.6l-4.7-6.3L5.8 21H3.5l6.6-7.9L4 3Zm3.5 2 9.4 14h1.6L9.1 5H7.5Z"/></svg>;return <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="5" width="20" height="14" rx="4"/><path className="play-shape" d="m10 9 5 3-5 3Z"/></svg>}
