export function Footer(){const south=window.location.pathname.includes('south')||window.location.pathname==='/felicitation/';const content=useForumContent(south?'south':'india');const s=content?.settings||{};const socials=[['linkedin',s.linkedin_url||'#linkedin'],['instagram',s.instagram_url||'#instagram'],['facebook',s.facebook_url||'#facebook'],['x',s.x_url||'#x'],['youtube',s.youtube_url||'#youtube']];return <footer className="ref-footer"><div><img src={A('2025/07/Logo.jpg')} alt="Retail Jeweller India Forum"/><p>{s.footer_tagline||'A Knowledge and Networking Platform where Forward-Thinking Jewellers Meet!'}</p></div><div><b>Social Media</b><p className="footer-social">{socials.map(([name,url])=><a href={url} key={name} aria-label={name} target={url.startsWith('#')?undefined:'_blank'} rel={url.startsWith('#')?undefined:'noreferrer'}><SocialIcon type={name}/></a>)}</p><Link to="/privacy-policy/">Policy</Link><p>{s.footer_copyright||'Copyright © 2025 Retail Jeweller. All Rights Reserved'}</p></div></footer>}
