function SpeakerGrid({speakers,limit,portraits=true}){const visible=limit?speakers.slice(0,limit):speakers;return <div className={`speaker-grid ${portraits?'':'speaker-grid-text'}`}>{visible.map((speaker,index)=><article className="speaker-card" key={`${speaker.name}-${index}`}>{portraits&&<SpeakerPortrait speaker={speaker}/>}<div><h3>{speaker.name}</h3><p>{speaker.role}</p></div></article>)}</div>}
function PostAgendaBanner({settings,south=false}){if(settings.post_agenda_banner_visible===0)return null;const fallback=A(`2026/09/${south?'south-forum':'India-Forum'}-banner_01.jpeg`);return <section className="post-agenda-banner" style={{backgroundImage:`url(${settings.post_agenda_banner_url||fallback})`}} aria-label={`${south?'South':'India'} Forum registration`}><div className="post-agenda-actions"><Button light href={settings.post_agenda_banner_target||'#passes'}>{settings.post_agenda_banner_label||'Register'}</Button><Button light href={south?'/exhibition-south/':'/exhibition/'}>Exhibit</Button></div></section>}
function PromotionalBanner({settings,south=false}){if(settings.quote_visible===0)return null;const image=settings.quote_banner_url||(!south?A('2026/09/retail-reimagined-india-forum-27.png'):'');if(!image)return null;return <section className="home-promo-banner"><a href={settings.quote_banner_target||'#passes'} aria-label={`${south?'South':'India'} Forum promotion`}><img src={image} alt={`${south?'South':'India'} Forum promotional banner`}/></a></section>}

