function Partner({path}){const [open,setOpen]=useState(0);const [enquiryOpen,setEnquiryOpen]=useState(false);return <div className="reference-site partner-page"><SiteHeader path={path}/><SocialRail/><section className="partner-hero" style={{backgroundImage:`url(${A('2025/07/Exhibit.jpg')})`}}/><section className="partner-intro"><img src={A('2025/08/c1f752c1cc8765a4dc3f148ec52602d3de956bc2.webp')} alt="Retail Jeweller India Forum stage"/><div><h1>Partner with India’s Premier Jewellery Leadership Platform</h1><p>Since 2005, the Retail Jeweller India Forum has united 300+ top retailers, manufacturers, and industry leaders to spark strategic dialogue and drive progress. Renowned for meaningful conversations and actionable insights, RJIF remains the most trusted platform for industry exchange, recognition, and innovation.</p><Button onClick={()=>setEnquiryOpen(true)}>Partner Now</Button></div></section><section className="ref-section sponsor-benefits"><SectionTitle>Why Sponsor RJIF 2027?</SectionTitle><div>{['300+ curated decision-makers from across India’s retail and manufacturing landscape','Branding before, during and after the event — digital + on-ground + media integration','Prime access to CEOs, MDs, Retail Heads, and Design Leaders','Association with MD & CEO Awards, India’s most prestigious industry honour','Curated formats for deeper brand engagement (luncheons, panel sessions, kits, and more)'].map((text,index)=><article key={text}><b>{String(index+1).padStart(2,'0')}</b><p>{text}</p></article>)}<img src={A('2025/07/Im-1.jpg')} alt="Retail Jeweller Forum delegate materials"/></div></section><section className="sponsorship-table"><h2>Sponsorship Element</h2>{sponsorships.map((row,index)=><article className={open===index?'open':''} key={row[0]}><button onClick={()=>setOpen(open===index?-1:index)}><b>{row[0]}</b><span>⌄</span></button><p>{row[1]}</p><strong>{row[2]}</strong></article>)}</section><section className="partner-cta"><div><h2>Let’s Create Impact Together</h2><p>Whether you want to build brand visibility, connect with retail leadership, or be part of India’s most influential jewellery awards — RJIF offers curated, high-impact opportunities.</p></div><div><h2>Partner Now</h2><p>For bookings or custom sponsorship ideas:</p><b>Chirag Waghela</b><a href="mailto:chirag.waghela@retailjewellerindia.com">chirag.waghela@retailjewellerindia.com</a><a href="tel:+919167252611">+91 91672 52611</a></div></section><Contacts variant="partner"/><Footer/><EnquiryModal type="Partnership enquiry" open={enquiryOpen} onClose={()=>setEnquiryOpen(false)}/></div>}

function Policy({path}){return <div className="reference-site policy-page"><SiteHeader path={path}/><SocialRail/><main><h1>Policy</h1><section><h2>1. Privacy Policy</h2><p>Retail Jeweller India is committed to protecting your personal information and your right to privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard your data when you visit retailjewellerindiaforum.com or interact with our services.</p><h3>Information We Collect</h3><p>We may collect the following information:</p><ul><li>Name, email address, phone number, company/organization name</li><li>Billing and payment information when purchasing event tickets or services</li><li>Any information submitted through forms, registrations, or inquiries</li><li>Technical data such as IP address, browser type, device information, and pages visited</li></ul><h3>How We Use Your Information</h3><ul><li>Event registration and ticket processing</li><li>Sending confirmations, updates, and support messages</li><li>Improving website performance and user experience</li><li>Marketing or promotional communication (only with your consent)</li><li>Compliance with legal requirements</li></ul><h3>Sharing of Information</h3><p>We do not sell or trade your personal information. We may share your data with payment gateways such as Razorpay, event partners or service providers, and legal authorities when required by law.</p><h3>Cookies &amp; Tracking</h3><p>We use cookies to personalise user experience, improve website functionality, and track analytics. You may disable cookies through your browser settings.</p><h3>Data Security</h3><p>We implement strict security measures to protect your data. However, no online platform is 100% secure; users share information at their own risk.</p><h3>Your Rights</h3><ul><li>Access to your data</li><li>Correction or deletion of your data</li><li>Removal from marketing communication</li></ul></section><section><h2>2. Terms &amp; Conditions</h2><p>By accessing or using retailjewellerindiaforum.com, you agree to these Terms &amp; Conditions.</p><h3>Use of Website</h3><ul><li>Content is for general information regarding our events, conferences, exhibitions, and awards.</li><li>You may not reproduce, distribute, or modify website content without written permission.</li></ul><h3>Event Registrations &amp; Payments</h3><ul><li>All event registrations are processed through secure payment gateways.</li><li>Prices are subject to change without prior notice.</li><li>Your registration is confirmed only after successful payment.</li></ul><h3>Third-Party Links</h3><p>Our website may contain links to external websites. We are not responsible for their content or policies.</p></section><section><h2>3. Refund &amp; Cancellation Policy</h2><h3>Event Tickets / Registrations</h3><ul><li>All purchases made on Retail Jeweller India Forum are non-refundable unless the event is cancelled by us.</li><li>If an event is postponed, tickets will automatically be valid for the new dates.</li><li>In case of cancellation by the organizer, a full refund will be issued to the original payment method.</li></ul><h3>User-Requested Cancellations</h3><ul><li>No refund is provided for voluntary cancellations or no-shows.</li></ul><h3>Payment Gateway Charges</h3><ul><li>Any convenience or payment gateway fees are non-refundable.</li></ul></section><section><h2>4. Shipping &amp; Delivery Policy</h2><p>(For digital passes, event badges, or documents)</p><ul><li>Most event communications, passes, or QR codes are delivered digitally via email or WhatsApp.</li><li>Physical items (if applicable) will be provided on-site at the event venue.</li><li>Delivery timelines depend on the event schedule and communication process.</li></ul></section><section><h2>5. Contact Us</h2><p>For questions regarding this Policy, please contact:</p><p><b>Retail Jeweller India</b><br/>Email: <a href="mailto:laxmi.gupta@retailjewellerindia.com">laxmi.gupta@retailjewellerindia.com</a><br/>Phone: <a href="tel:+917738352502">+91 77383 52502</a><br/>Website: <a href="https://retailjewellerindiaforum.com/">https://retailjewellerindiaforum.com/</a></p></section></main><Footer/></div>}

const checkoutPasses={
  'india-single':{code:'india-single',name:'India Forum — Single Pass',sale_price_paise:750000,tax_rate:18,member_count:1},'india-corporate':{code:'india-corporate',name:'India Forum — Corporate Pass',sale_price_paise:1800000,tax_rate:18,member_count:3},'india-leadership':{code:'india-leadership',name:'India Forum — Leadership Pass',sale_price_paise:2500000,tax_rate:18,member_count:5},'india-non-retailer':{code:'india-non-retailer',name:'India Forum — Non-Retailer Pass',sale_price_paise:1000000,tax_rate:18,member_count:1},'south-group':{code:'south-group',name:'South Forum — Group Pass',sale_price_paise:900000,tax_rate:18,member_count:3},'south-non-retailer':{code:'south-non-retailer',name:'South Forum — Non-Retailer Pass',sale_price_paise:750000,tax_rate:18,member_count:1},'south-retailer':{code:'south-retailer',name:'South Forum — Retailer Individual Pass',sale_price_paise:375000,tax_rate:18,member_count:1},'awards-registration':{code:'awards-registration',name:'Business Excellence Awards Registration',sale_price_paise:5000000,tax_rate:18,member_count:1}
};
function Checkout({path}){
  const search=new URLSearchParams(window.location.search),selected=search.get('pass'),complimentary=search.get('complimentary')||'',awardApplication=search.get('application')||'';
  const [idempotencyKey]=useState(()=>window.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`);
  const [pass,setPass]=useState(checkoutPasses[selected]||null);
  const [loading,setLoading]=useState(!checkoutPasses[selected]);
  const [quantity,setQuantity]=useState(1);
  const [collectAttendees,setCollectAttendees]=useState(false);
  const [submitting,setSubmitting]=useState(false),[result,setResult]=useState(null),[error,setError]=useState('');
  useEffect(()=>{let active=true;const params=new URLSearchParams({code:selected||''});if(complimentary)params.set('complimentary',complimentary);api(`/public/products?${params}`).then(rows=>{const found=rows.find(item=>item.code===selected);if(active)setPass(found||null)}).catch(()=>active&&setPass(null)).finally(()=>active&&setLoading(false));return()=>{active=false}},[selected,complimentary]);
  const members=Math.max(1,Number(pass?.member_count)||1);
  const attendeeCount=members*quantity;
  const unitPrice=Number(pass?.sale_price_paise||0);
  const subtotal=unitPrice*quantity;
  const taxAmount=Math.round(subtotal*(Number(pass?.tax_rate)||0)/100);
  const grandTotal=subtotal+taxAmount;
  const changeQuantity=next=>setQuantity(Math.min(20,Math.max(1,next)));
  async function openPayment(registration){const loaded=window.Razorpay||await new Promise(resolve=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=()=>resolve(window.Razorpay);script.onerror=()=>resolve(null);document.head.appendChild(script)});if(!loaded)throw new Error('Secure payment window could not load. Please try again.');const g=registration.gateway;new loaded({key:g.keyId,order_id:g.orderId,amount:g.amount,currency:g.currency,name:g.name,prefill:g.prefill,description:'Delegate pass registration',handler:async response=>{try{const confirmed=await api('/public/payments/razorpay/verify',{method:'POST',body:JSON.stringify(response)});setResult({...registration,status:'confirmed',manageUrl:confirmed.manageUrl,message:'Payment confirmed. Your QR passes are ready.'})}catch(e){setError(e.message)}}}).open()}
  async function submit(event){event.preventDefault();setSubmitting(true);setError('');const data=new FormData(event.currentTarget);const attendees=collectAttendees?Array.from({length:attendeeCount},(_,index)=>({full_name:data.get(`attendee_name_${index}`),email:data.get(`attendee_email_${index}`),phone:data.get(`attendee_phone_${index}`)})):[];try{const registration=await api('/public/checkout',{method:'POST',body:JSON.stringify({product_code:pass.code,quantity,customer_name:data.get('customer_name'),company:data.get('company'),email:data.get('email'),phone:data.get('phone'),gstin:data.get('gstin'),billing_address:data.get('billing_address'),consent:Boolean(data.get('consent')),attendees,idempotency_key:idempotencyKey,complimentary_token:complimentary,award_application_id:awardApplication,policy_version:'2026-10-06'})});if(registration.gateway)await openPayment(registration);else setResult(registration)}catch(e){setError(e.message)}finally{setSubmitting(false)}}
  return <div className="reference-site checkout-page"><SiteHeader path={path}/><main><header className="checkout-heading"><p>Secure registration</p><h1>Complete your booking</h1><span>Confirmed registrations receive individual QR passes by email.</span></header>{result?<section className="checkout-result"><span className="result-check">✓</span><h2>{result.status==='confirmed'?'Registration confirmed':'Registration received'}</h2><p>{result.message}</p><Link className="ref-button" to={result.manageUrl}>View registration</Link></section>:loading?<div className="status">Loading pass…</div>:pass?<div className="checkout-grid"><section className="checkout-summary"><div className="checkout-summary-head"><p className="eyebrow">Selected pass</p><span>{pass.forum==='south'?'South Forum':'India Forum'}</span></div><h2>{pass.name}</h2>{pass.description&&<p className="checkout-description">{pass.description}</p>}<div className="checkout-pass-meta"><span><b>{members}</b>{members===1?' attendee':' attendees'} per pass</span><span><b>QR</b> digital entry</span></div><div className="quantity-row"><div><b>Quantity</b><small>Maximum 20 passes</small></div><div className="quantity-stepper"><button type="button" onClick={()=>changeQuantity(quantity-1)} disabled={quantity===1}>−</button><input aria-label="Quantity" type="number" min="1" max="20" value={quantity} onChange={event=>changeQuantity(Number(event.target.value)||1)}/><button type="button" onClick={()=>changeQuantity(quantity+1)} disabled={quantity===20}>+</button></div></div><div className="price-breakdown"><div><span>{money(unitPrice)} × {quantity}</span><b>{money(subtotal)}</b></div>{taxAmount>0&&<div><span>GST ({pass.tax_rate}%)</span><b>{money(taxAmount)}</b></div>}<div className="checkout-total"><span>Total</span><strong>{subtotal===0?'Complimentary':money(grandTotal)}</strong></div></div></section><form onSubmit={submit}><div className="checkout-form-head"><span>2</span><div><p className="eyebrow">Contact information</p><h2>Billing details</h2></div></div>{error&&<p className="error">{error}</p>}<div className="checkout-form-grid"><label>Full name<input name="customer_name" autoComplete="name" required/></label><label>Company<input name="company" autoComplete="organization" required/></label><label>Email<input name="email" type="email" autoComplete="email" required/></label><label>Mobile number<input name="phone" type="tel" autoComplete="tel" required/></label><label>GSTIN <small>Optional</small><input name="gstin"/></label><label className="full-width">Billing address<textarea name="billing_address" rows="3" autoComplete="street-address" required/></label></div>{members>1&&<label className="checkout-attendee-toggle"><input type="checkbox" checked={collectAttendees} onChange={event=>setCollectAttendees(event.target.checked)}/><span>Add attendee details now<small>Company bookings can submit names after payment.</small></span></label>}{collectAttendees&&<fieldset className="attendee-fields"><legend>Attendee details</legend>{Array.from({length:attendeeCount},(_,index)=><div key={index}><h3>Attendee {index+1}</h3><label>Name<input name={`attendee_name_${index}`} required/></label><label>Email<input name={`attendee_email_${index}`} type="email" required/></label><label>Mobile number<input name={`attendee_phone_${index}`} type="tel" required/></label></div>)}</fieldset>}<label className="consent"><input name="consent" type="checkbox" required/><span>I agree to the terms, privacy, refund and cancellation policies.</span></label><button className="ref-button checkout-submit" disabled={submitting}>{submitting?'Submitting…':subtotal===0?'Confirm complimentary pass':`Continue with ${money(grandTotal)}`}</button>{subtotal>0&&<small className="checkout-status">Your QR passes are issued only after payment is confirmed.</small>}</form></div>:<div className="empty-cart"><h2>Your cart is empty</h2><p>Select a delegate pass from the India or South Forum page.</p><Link className="ref-button" to="/#passes">View India passes</Link></div>}</main><Footer/></div>
}

function DelegatePass({path}){const token=new URLSearchParams(window.location.search).get('token');const [state,setState]=useState({loading:true});useEffect(()=>{api(`/public/passes/${encodeURIComponent(token||'')}`).then(pass=>setState({pass})).catch(error=>setState({error:error.message}))},[token]);return <div className="reference-site checkout-page"><SiteHeader path={path}/><main className="pass-view">{state.loading?<div className="status">Loading pass…</div>:state.error?<div className="empty-cart"><h2>Pass unavailable</h2><p>{state.error}</p></div>:<article className="digital-pass"><header><p>Retail Jeweller {state.pass.forum==='south'?'South':'India'} Forum</p><b>DELEGATE PASS</b></header><h1>{state.pass.full_name||'Delegate'}</h1><p>{state.pass.company}</p><img src={`/api/public/passes/${encodeURIComponent(token)}/qr.svg`} alt="Delegate entry QR code"/><code>{state.pass.pass_number}</code><dl><div><dt>Date</dt><dd>{state.pass.event_date}</dd></div><div><dt>Location</dt><dd>{state.pass.event_location}</dd></div></dl><strong className={`pass-state ${state.pass.status}`}>{state.pass.status.replace('_',' ')}</strong><a className="ref-button" href={`/api/public/passes/${encodeURIComponent(token)}/pdf`}>Download PDF pass</a></article>}</main><Footer/></div>}

function Registration({path}){
  const token=new URLSearchParams(window.location.search).get('token');
  const [order,setOrder]=useState(null),[error,setError]=useState(''),[saving,setSaving]=useState(false);
  const load=useCallback(()=>api(`/public/orders/${encodeURIComponent(token||'')}`).then(setOrder).catch(e=>setError(e.message)),[token]);
  useEffect(()=>{load()},[load]);
  async function continuePayment(){setSaving(true);setError('');try{const registration=await api(`/public/orders/${encodeURIComponent(token)}/payment`,{method:'POST',body:'{}'});const Razorpay=window.Razorpay||await new Promise(resolve=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=()=>resolve(window.Razorpay);script.onerror=()=>resolve(null);document.head.appendChild(script)});if(!Razorpay)throw new Error('Secure payment window could not load. Please try again.');const g=registration.gateway;new Razorpay({key:g.keyId,order_id:g.orderId,amount:g.amount,currency:g.currency,name:g.name,prefill:g.prefill,description:'Delegate pass registration',handler:async response=>{await api('/public/payments/razorpay/verify',{method:'POST',body:JSON.stringify(response)});await load()}}).open()}catch(e){setError(e.message)}finally{setSaving(false)}}
  async function saveAttendees(event){event.preventDefault();setSaving(true);setError('');const data=new FormData(event.currentTarget),attendees=Array.from({length:order.capacity},(_,index)=>({full_name:data.get(`name_${index}`),email:data.get(`email_${index}`),phone:data.get(`phone_${index}`)}));try{await api(`/public/orders/${encodeURIComponent(token)}/attendees`,{method:'POST',body:JSON.stringify({attendees})});await load()}catch(e){setError(e.message)}finally{setSaving(false)}}
  if(error&&!order)return <div className="reference-site checkout-page"><SiteHeader path={path}/><main><div className="empty-cart"><h2>Registration unavailable</h2><p>{error}</p></div></main><Footer/></div>;
  return <div className="reference-site checkout-page"><SiteHeader path={path}/><main className="registration-view">{!order?<div className="status">Loading registration…</div>:<section><p className="eyebrow">Registration {order.public_id}</p><h1>{order.product_name}</h1><p><b>Status:</b> {order.status.replace('_',' ')}</p>{error&&<p className="error">{error}</p>}{!['paid','cancelled','refunded'].includes(order.status)&&<button className="ref-button" onClick={continuePayment} disabled={saving}>{saving?'Opening payment…':'Continue secure payment'}</button>}{order.passes.length?<div className="pass-links">{order.passes.map(pass=><Link className="ref-button" key={pass.pass_number} to={pass.viewUrl}>Open pass — {pass.pass_number}</Link>)}</div>:order.status==='paid'&&order.attendees.length===0?<form className="attendee-fields registration-attendees" onSubmit={saveAttendees}><h2>Add attendee details</h2><p>Enter the people who will use these passes. Each person receives an individual QR code.</p>{Array.from({length:order.capacity},(_,index)=><div key={index}><h3>Attendee {index+1}</h3><label>Name<input name={`name_${index}`} required/></label><label>Email<input name={`email_${index}`} type="email" required/></label><label>Mobile<input name={`phone_${index}`} required/></label></div>)}<button className="ref-button" disabled={saving}>{saving?'Issuing passes…':'Issue attendee passes'}</button></form>:order.status==='paid'?<p>Your passes are being prepared. Refresh this page shortly.</p>:<p>Passes will appear after payment is confirmed.</p>}</section>}</main><Footer/></div>}
function Account({path}){return <div className="reference-site checkout-page"><SiteHeader path={path}/><main><SectionTitle>My Account</SectionTitle><div className="checkout-grid"><section><h2>Access your registrations</h2><p>Once staging email is connected, purchasers will receive a secure sign-in link to view orders, invoices, payment status, and digital passes. Passwords are not required.</p></section><form><label>Email address<input type="email" required/></label><button className="ref-button" type="button" disabled>Email secure sign-in link</button><small>Account email is disabled until the staging mail provider is configured.</small></form></div></main><Footer/></div>}

const referenceUi={SiteHeader,SocialRail,YoutubeVideo,Gallery,Contacts,Footer,Button,asset:A};

export default function ReferencePage({path}){const normalized=path.endsWith('/')?path:`${path}/`;const south=normalized.includes('south');const component=useMemo(()=>{if(normalized==='/delegate-pass/')return <DelegatePass path={normalized}/>;if(normalized==='/registration/')return <Registration path={normalized}/>;if(normalized==='/exhibition/'||normalized==='/exhibition-south/')return <Exhibition south={south} path={normalized}/>;if(normalized==='/speakers/'||normalized==='/south-forum-speakers/')return <Speakers south={south} path={normalized}/>;if(normalized==='/business-excellence-awards/'||normalized==='/leadership-awards/')return <BusinessExcellencePage path={normalized} ui={referenceUi}/>;if(normalized==='/previous-edition-highlights/')return <Highlights path={normalized}/>;if(normalized==='/partner/')return <Partner path={normalized}/>;if(normalized==='/felicitation/')return <FelicitationPage path={normalized} ui={referenceUi}/>;if(normalized==='/privacy-policy/')return <Policy path={normalized}/>;if(normalized==='/my-account/')return <Account path={normalized}/>;if(['/cart/','/checkout/'].includes(normalized))return <Checkout path={normalized}/>;if(normalized==='/'||normalized==='/conference-south/')return <Home south={south} path={normalized}/>;return null},[normalized,south]);return component}
